cat > ~/fill.py <<'EOF'
import workcell, sys, re
jar=sys.argv[1]
def call(*a):
    r=workcell.call(*a); 
    if not r.ok: print("FAIL",a,r.text); sys.exit(1)
    return r
def read():
    return float(call("scale","read").data.get("reading_g", None) if isinstance(call, object) else 0)
call("robot","pick",jar)
call("robot","place","platform")
call("scale","tare")
def rd():
    r=call("scale","read")
    return float(r.data["reading_g"])
v=rd(); print("start",v)
while v < 190:
    call("robot","dose","bulk"); v=rd()
while v < 238:
    call("robot","dose","coarse"); v=rd()
while v < 249.0:
    call("robot","dose","fine"); v=rd()
    print("fine",v)
while v < 249.90:
    call("robot","dose","micro"); v=rd()
    print("micro",v)
while v > 250.15:
    call("robot","remove"); v=rd(); print("rem",v)
    while v < 249.0:
        call("robot","dose","fine"); v=rd()
    while v < 249.90:
        call("robot","dose","micro"); v=rd()
r=call("checkweigher","check")
print("LABEL:",r.text)
call("robot","pick",jar)
call("robot","place","rack")
EOF
python3 ~/fill.py J1

